using Microsoft.EntityFrameworkCore;
class AppDbContext : DbContext
{
    public DbSet<Order> Orders => Set<Order>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: HasData() no longer uses DateTime.UtcNow
        // (non-deterministic seed data causes spurious migrations).
        // Use a fixed value instead.
        modelBuilder.Entity<Order>().HasData(
            new Order { Id = 1, CreatedAt = new DateTime(2024, 1, 1, 0, 0, 0, DateTimeKind.Utc) });
    }
}
class Order { public int Id { get; set; } public DateTime CreatedAt { get; set; } }

// --- Cosmos DB context demonstrating EF Core 9 breaking changes ---

class CosmosDbContext : DbContext
{
    public DbSet<Vehicle> Vehicles => Set<Vehicle>();

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        optionsBuilder.UseCosmos(
            "https://localhost:8081",
            "C2y6yDjf5/R+ob0N8A7Cgv30VRDJIWEHLM+4QDU5DE2nQ9nDuVTqobD4b8mGGyPMbIZnqyMsEcaGQy67XIw/Jw==",
            "EfAppDb");
    }

    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // EF Core 9 breaking change: The Cosmos provider now uses "$type" instead of
        // "Discriminator" for the discriminator property by default.
        // To maintain compatibility with existing documents that use "Discriminator",
        // explicitly configure the discriminator property name.
        modelBuilder.Entity<Vehicle>(b =>
        {
            b.ToContainer("Vehicles");
            b.HasDiscriminator<string>("Discriminator")
                .HasValue<Vehicle>("Vehicle")
                .HasValue<Car>("Car")
                .HasValue<Truck>("Truck");
        });
    }
}

class Vehicle
{
    public string Id { get; set; } = null!;
    public string Make { get; set; } = null!;
}
class Car : Vehicle { public int Seats { get; set; } }
class Truck : Vehicle { public double PayloadTons { get; set; } }

// --- Cosmos DB queries: EF Core 9 removed synchronous I/O support ---

class CosmosQueryService
{
    private readonly CosmosDbContext _db;
    public CosmosQueryService(CosmosDbContext db) => _db = db;

    // EF Core 9 breaking change: Synchronous operations (ToList, First, Count, etc.)
    // now throw InvalidOperationException on the Cosmos provider.
    // All queries MUST use async equivalents.
    public async Task<List<Vehicle>> GetAllVehiclesAsync()
    {
        // BEFORE (broken in EF Core 9):
        //   return _db.Vehicles.ToList();
        // AFTER:
        return await _db.Vehicles.ToListAsync();
    }

    public async Task<Vehicle?> GetVehicleAsync(string id)
    {
        // BEFORE (broken in EF Core 9):
        //   return _db.Vehicles.FirstOrDefault(v => v.Id == id);
        // AFTER:
        return await _db.Vehicles.FirstOrDefaultAsync(v => v.Id == id);
    }
}

